### Analyze an image with a text prompt in generate() content

Source: https://github.com/mastra-ai/mastra/blob/main/docs/src/content/en/reference/agents/generate.mdx

Pass a content array containing an image part (absolute URL, data URL, or base64) and a text part to have the agent describe the image and extract its text. Relative paths are not visible to the model.

```typescript
const response = await agent.generate([
  {
    role: 'user',
    content: [
      {
        type: 'image',
        image: 'https://placebear.com/cache/395-205.jpg',
        mimeType: 'image/jpeg',
      },
      {
        type: 'text',
        text: 'Describe the image in detail, and extract all the text in the image.',
      },
    ],
  },
])

console.log(response.text)

```

--------------------------------

### Generate structured output with agent.network

Source: https://github.com/mastra-ai/mastra/blob/main/docs/src/content/en/reference/agents/network.mdx

Pass a Zod schema to structuredOutput in agent.network to generate and resolve typed, validated results after task completion.

```typescript
import { z } from 'zod'

const resultSchema = z.object({
  summary: z.string().describe('A brief summary of the findings'),
  recommendations: z.array(z.string()).describe('List of recommendations'),
  confidence: z.number().min(0).max(1).describe('Confidence score'),
})

const stream = await agent.network('Research AI trends and summarize', {
  structuredOutput: {
    schema: resultSchema,
  },
})

// Consume the stream
for await (const chunk of stream) {
  // Handle streaming events
}

// Get the typed result
const result = await stream.object
// result is typed as { summary: string; recommendations: string[]; confidence: number }
console.log(result?.summary)
console.log(result?.recommendations)
```

--------------------------------

### Define structured output schema with Zod

Source: https://github.com/mastra-ai/mastra/blob/main/docs/src/content/en/docs/agents/structured-output.mdx

Use Zod to define the expected output shape for an agent's structured response. The validated, typed result is available via `response.object`.

```typescript
import { z } from 'zod'

const response = await testAgent.generate('Help me plan my day.', {
  structuredOutput: {
    schema: z.array(
      z.object({
        name: z.string(),
        activities: z.array(z.string()),
      }),
    ),
  },
})

console.log(response.object)
```

--------------------------------

### Multimodal input: attachments converted to image and file content parts

Source: https://github.com/mastra-ai/mastra/blob/main/packages/core/src/agent/message-list/prompt/attachments-to-parts.ts

The documented attachment API that turns user-supplied images (URLs, data URIs, base64, gs://, s3://) and non-image files (audio/video/etc.) into AI SDK `image` and `file` content parts sent to multimodal models. Images become `{ type: 'image' }` parts; everything else with a content type becomes `{ type: 'file' }` parts.

```typescript
export function attachmentsToParts(attachments: Attachment[]): ContentPart[] {
  const parts: ContentPart[] = [];

  for (const attachment of attachments) {
    // Categorize the attachment URL to determine if it's a URL, data URI, raw base64,
    // or a provider file ID (e.g. OpenAI "file-...")
    const categorized = categorizeFileData(attachment.url, attachment.contentType);

    // Provider file IDs are not parseable URLs — pass them through as file parts
    // untouched so providers can forward them by reference (e.g. { file_id: "file-..." }).
    if (categorized.type === 'providerFileId') {
      parts.push({
        type: 'file',
        data: attachment.url,
        mimeType: attachment.contentType || 'application/octet-stream',
      });
      continue;
    }

    // If it's raw data (base64), convert it to a data URI
    let urlString = attachment.url;
    if (categorized.type === 'raw') {
      urlString = createDataUri(attachment.url, attachment.contentType || 'application/octet-stream');
    }

    let url;
    try {
      url = new URL(urlString);
    } catch {
      throw new Error(`Invalid URL: ${attachment.url}`);
    }

    switch (url.protocol) {
      case 'http:':
      case 'https:':
      // Cloud storage protocols supported by AI providers (e.g., Vertex AI for gs://, Bedrock for s3://)
      case 'gs:':
      case 's3:': {
        if (attachment.contentType?.startsWith('image/')) {
          parts.push({ type: 'image', image: url.toString(), mimeType: attachment.contentType });
        } else {
          if (!attachment.contentType) {
            throw new Error('If the attachment is not an image, it must specify a content type');
          }

          parts.push({
            type: 'file',
            data: url.toString(),
            mimeType: attachment.contentType,
          });
        }
        break;
      }

      case 'data:': {
        if (attachment.contentType?.startsWith('image/')) {
          parts.push({
            type: 'image',
            image: urlString,
            mimeType: attachment.contentType,
          });
        } else if (attachment.contentType?.startsWith('text/')) {
          parts.push({
            type: 'file',
            data: urlString,
            mimeType: attachment.contentType,
          });
        } else {
          if (!attachment.contentType) {
            throw new Error('If the attachment is not an image or text, it must specify a content type');
          }

          parts.push({
            type: 'file',
            data: urlString,
            mimeType: attachment.contentType,
          });
        }

        break;
      }

      default: {
        throw new Error(`Unsupported URL protocol: ${url.protocol}`);
      }
    }
  }

  return parts;
}
```

